{"content":"{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "JiMesh Tier Definition",
  "description": "Schema for defining model tiers in JiMesh",
  "type": "object",
  "required": ["tier_id", "tier_name", "tier_description", "tier_priority", "tier_emoji", "tier_color", "intelligence_rank_min", "intelligence_rank_max", "models"],
  "properties": {
    "tier_id": {
      "type": "string",
      "pattern": "^(s-tier|a-tier|b-tier|c-tier)$",
      "description": "Unique tier identifier (s-tier, a-tier, b-tier, c-tier)"
    },
    "tier_name": {
      "type": "string",
      "description": "Human-readable tier name"
    },
    "tier_description": {
      "type": "string",
      "description": "Detailed description of this tier's purpose"
    },
    "tier_priority": {
      "type": "integer",
      "minimum": 1,
      "maximum": 10,
      "description": "Priority order (1 = highest/S-Tier)"
    },
    "tier_emoji": {
      "type": "string",
      "description": "Unicode emoji for UI display"
    },
    "tier_color": {
      "type": "string",
      "pattern": "^#[0-9a-fA-F]{6}$",
      "description": "Hex color code for UI theming"
    },
    "intelligence_rank_min": {
      "type": "integer",
      "minimum": 1,
      "maximum": 999,
      "description": "Minimum intelligence rank (1 = best)"
    },
    "intelligence_rank_max": {
      "type": "integer",
      "minimum": 1,
      "maximum": 999,
      "description": "Maximum intelligence rank (999 = no limit)"
    },
    "model_count": {
      "type": "integer",
      "minimum": 0,
      "description": "Total number of models in this tier"
    },
    "platforms_required": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "List of provider IDs required for this tier"
    },
    "platform_counts": {
      "type": "object",
      "patternProperties": {
        "^[a-z0-9-]+$": {
          "type": "integer",
          "minimum": 0
        }
      },
      "description": "Number of models per provider in this tier"
    },
    "models": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["priority", "provider_id", "model_id", "display_name", "intelligence_rank", "supports_vision", "supports_tools"],
        "properties": {
          "priority": {
            "type": "integer",
            "minimum": 1,
            "description": "Priority within tier (1 = highest)"
          },
          "provider_id": {
            "type": "string",
            "description": "Provider platform identifier"
          },
          "model_id": {
            "type": "string",
            "description": "Provider-specific model ID"
          },
          "display_name": {
            "type": "string",
            "description": "Human-readable model name"
          },
          "intelligence_rank": {
            "type": "integer",
            "minimum": 1,
            "maximum": 999,
            "description": "Intelligence rank (1 = best)"
          },
          "supports_vision": {
            "type": "boolean",
            "description": "Whether model supports vision/multimodal input"
          },
          "supports_tools": {
            "type": "boolean",
            "description": "Whether model supports function/tool calling"
          },
          "context_window": {
            "type": "integer",
            "minimum": 0,
            "description": "Context window size in tokens"
          },
          "max_output_tokens": {
            "type": "integer",
            "minimum": 0,
            "description": "Maximum output tokens"
          }
        }
      },
      "description": "Ordered list of models in this tier"
    }
  },
  "additionalProperties": false
}","file_path":"/home/ji/projects/jimesh/data/chains/schemas/tier.schema.json"}

