{"content": "{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "JiMesh Provider Configuration",
  "description": "Schema for provider API key requirements",
  "type": "object",
  "required": ["provider_id", "provider_name", "api_key_format", "tiers_served", "models_count", "priority"],
  "properties": {
    "provider_id": {
      "type": "string",
      "description": "Provider platform identifier"
    },
    "provider_name": {
      "type": "string",
      "description": "Human-readable provider name"
    },
    "api_key_format": {
      "type": "string",
      "enum": ["bearer", "api-key", "oauth", "none"],
      "description": "How to authenticate with this provider"
    },
    "tiers_served": {
      "type": "array",
      "items": {
        "type": "string",
        "pattern": "^(s-tier|a-tier|b-tier|c-tier)$"
      },
      "description": "Which tiers this provider serves"
    },
    "models_count": {
      "type": "integer",
      "minimum": 0,
      "description": "Number of models from this provider"
    },
    "priority": {
      "type": "string",
      "enum": ["critical", "high", "medium", "low"],
      "description": "How important is this provider"
    },
    "signup_url": {
      "type": "string",
      "format": "uri",
      "description": "Where to get API key"
    },
    "free_tier": {
      "type": "boolean",
      "description": "Has a free tier"
    },
    "rate_limit": {
      "type": "integer",
      "minimum": 0,
      "description": "Requests per minute limit"
    },
    "notes": {
      "type": "string",
      "description": "Additional notes about this provider"
    }
  },
  "additionalProperties": false
}", "file_path": "/home/ji/projects/jimesh/data/chains/schemas/provider.schema.json"}

