import json
from collections import defaultdict

# Load provider data
with open('data/chains/exports/provider-mapping.json') as f:
    provider_data = json.load(f)

# Create tier-provider mapping
tier_map = {
    "version": "1.0.0",
    "generated_at": "2026-08-30",
    "description": "Tier to provider mapping with primary/fallback classification",
    "tier_provider_map": {}
}

# Priority levels: critical > high > medium > low
priority_order = {"critical": 0, "high": 1, "medium": 2, "low": 3}

for tier_id in ["s-tier", "a-tier", "b-tier"]:
    primary = []
    fallback = []

    for provider_id, provider_info in provider_data["providers"].items():
        if tier_id in provider_info["tiers_served"]:
            provider_entry = {
                "provider_id": provider_id,
                "model_count": provider_info["model_count"],
                "priority": provider_info["priority"]
            }

            if provider_info["priority"] in ["critical", "high"]:
                primary.append(provider_entry)
            else:
                fallback.append(provider_entry)

    # Sort by priority then model count
    primary.sort(key=lambda x: (priority_order[x["priority"]], -x["model_count"]))
    fallback.sort(key=lambda x: (priority_order[x["priority"]], -x["model_count"]))

    tier_map["tier_provider_map"][tier_id] = {
        "tier_id": tier_id,
        "primary_providers": [p["provider_id"] for p in primary],
        "fallback_providers": [p["provider_id"] for p in fallback],
        "primary": primary,
        "fallback": fallback
    }

with open('data/chains/exports/tier-mapping.json', 'w') as f:
    json.dump(tier_map, f, indent=2, ensure_ascii=False)

print("tier-mapping.json created")
for tier_id, tier_info in tier_map["tier_provider_map"].items():
    print(f"  {tier_id}: {len(tier_info['primary_providers'])} primary, {len(tier_info['fallback_providers'])} fallback")
EOF"}

